//! SYNTHETIC storage/formula fixtures, never GCL admission proof.
//!
//! The Quantum exporter supplies real PD checkpoint/pending bytes but synthetic
//! layer/receipt material and request SHA [7; 32]. These tests exercise actual
//! transaction validation, WAL sync/replay and Shadow-owned T2 derivation.
//! They do not call native constitutional admission or seed production knowledge.
//! Ordinary Cargo uses pinned vectors regenerated byte-for-byte by Quantum tests.
//! Optional explicit exports stay isolated; no test order or environment setup is required.
use super::*;
use crate::knowledge_vault::{KnowledgeVault, VaultBackend};
use crate::native_cycle::{identity_digest, NativeCycleSnapshot, NativeRequestBinding};
use crate::shadow_commit::KnowledgeWrite;
use crate::sovereign_ffi_gate::VerificationReceipt;
use crate::types::{KnowledgeBand, LawConfirmedVerdict, NegativeContext, SupremeVerdict};
use crate::vault_disk::DiskBackend;
use crate::vault_transaction::{CommitStatus, VaultTransaction};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

mod pinned_fixture { include!(concat!(env!("CARGO_MANIFEST_DIR"), "/../test_support/prepared_fixture.rs")); }
fn fixture_bytes(kind: &str, name: &str, limit: usize) -> Vec<u8> {
    let pinned = pinned_fixture::bytes(kind, name);
    assert!(pinned.len() <= limit);
    match std::env::var_os("ESSMAI_PD_PREPARED_FIXTURE_DIR") {
        None => pinned.to_vec(),
        Some(base) => {
            let base = PathBuf::from(base);
            assert!(base.is_absolute());
            let actual = bounded_read(&base.join(kind).join(name), limit);
            assert_eq!(actual, pinned, "external fixture must match regenerated canonical test vector");
            actual
        }
    }
}

const NOTICE: &str = "SYNTHETIC STORAGE/FORMULA TEST ONLY. The prepared state uses real PD data, but the receipt, layers, request digest and knowledge payload are test fixtures. No native GCL admission and no real scientific knowledge are demonstrated. Run only against this isolated fixture WAL.\n";

struct Fixture {
    transaction: VaultTransaction,
    identity: [u8; 32],
    request_sha256: [u8; 32],
    expected: Vec<u8>,
}

fn bounded_read(path: &Path, limit: usize) -> Vec<u8> {
    let file = std::fs::File::open(path).expect("fixture file; first run Quantum exporter");
    assert!(
        file.metadata().unwrap().len() <= limit as u64,
        "fixture limit"
    );
    let mut bytes = Vec::new();
    file.take(limit as u64 + 1).read_to_end(&mut bytes).unwrap();
    assert!(bytes.len() <= limit);
    bytes
}

fn hex32(value: &str) -> [u8; 32] {
    assert_eq!(value.len(), 64, "fixture hex width");
    assert!(value.is_ascii(), "fixture ASCII hex");
    let mut out = [0u8; 32];
    for (index, byte) in out.iter_mut().enumerate() {
        *byte =
            u8::from_str_radix(&value[index * 2..index * 2 + 2], 16).expect("fixture hex digit");
    }
    out
}

// Map EVERY wire verdict field; no default-valued policy field is substituted.
fn supreme(w: &shadow_contracts::ShadowVerdictWire) -> SupremeVerdict {
    SupremeVerdict {
        verified: w.verified,
        primitive: w.primitive,
        knowledge_band: match w.knowledge_band {
            0 => KnowledgeBand::Negative,
            1 => KnowledgeBand::Hypothesis,
            2 => KnowledgeBand::Fact,
            3 => KnowledgeBand::Scientific,
            _ => panic!("unknown fixture knowledge band"),
        },
        lgc_law: w.lgc_law,
        legacy_score: w.legacy_score,
        lgc_dsl: w.lgc_dsl.clone(),
        living_trust_sha256: hex32(&w.living_trust_sha256),
        living_trust_intensity: w.living_trust_intensity,
        living_trust_kind: w.living_trust_kind,
        living_trust_action_state: w.living_trust_action_state,
        living_trust_action_mask: w.living_trust_action_mask,
        living_trust_required_action_mask: w.living_trust_required_action_mask,
        living_trust_system_laws_seal: w.living_trust_system_laws_seal,
        living_trust_sovereign_flags: w.living_trust_sovereign_flags,
        living_trust_sovereign_value: w.living_trust_sovereign_value,
        project_id: w.project_id,
        project_status: w.project_status,
        project_context_digest: w.project_context_digest,
        project_evidence_digest: w.project_evidence_digest,
        project_context_sha256: hex32(&w.project_context_sha256),
        project_evidence_sha256: hex32(&w.project_evidence_sha256),
        novel_factualized: w.novel_factualized,
        novel_trl_level: w.novel_trl_level,
        novel_proof_score: w.novel_proof_score,
        novel_rejection: w.novel_rejection,
    }
}

fn fixture(kind: &str, input_id: u64) -> Fixture {
    fixture_with_predecessor(kind, input_id, None)
}
fn fixture_with_predecessor(kind: &str, input_id: u64, predecessor: Option<&crate::vault_transaction::DurableCommit>) -> Fixture {
    assert!(matches!(kind, "positive" | "negative" | "followup-positive" | "followup-negative" | "stale-positive"));
    let mut prepared_bytes = fixture_bytes(kind, "prepared.bin", pd::MAX_PREPARED_BYTES);
    let mut prepared = pd::decode_prepared(&prepared_bytes).expect("canonical prepared fixture");
    assert_eq!(
        prepared.source_request_sha256, [7; 32],
        "declared synthetic request SHA"
    );
    let response_bytes = fixture_bytes(
        kind, "response.wire",
        crate::native_cycle::MAX_NATIVE_RESPONSE_BYTES,
    );
    let response = shadow_contracts::decode_cycle_response(&response_bytes)
        .expect("canonical synthetic response");
    assert_eq!(
        shadow_contracts::encode_cycle_response(&response),
        response_bytes
    );
    let mut expected = fixture_bytes(kind, "continuation.bin", pd::MAX_CONTINUATION_BYTES);
    pd::decode_continuation(&expected)
        .expect("canonical expected continuation")
        .validate_for(&prepared, &response)
        .expect("fixture's exact prepared/response binding");
    if let Some(predecessor) = predecessor {
        // Rebind the explicitly synthetic export's placeholder transaction ID
        // to the actual T1 committed by this isolated storage test.
        prepared.continuity.as_mut().expect("v2 link").predecessor_transaction_id=predecessor.transaction_id;
        prepared_bytes=pd::encode_prepared(&prepared).unwrap();
        expected=pd::encode_continuation(&pd::derive_continuation(&prepared,&response).unwrap()).unwrap();
    }
    let negative = kind.ends_with("negative");
    assert_eq!(
        (response.verdict.verified, response.verdict.primitive),
        if negative { (0, 0) } else { (1, 1) }
    );
    assert_eq!(response.negative_persisted, negative);

    let wire_receipt = &response.verification_receipt;
    let receipt = VerificationReceipt {
        session_id: wire_receipt.session_id.clone(),
        parent_i0: wire_receipt.parent_i0.clone(),
        primitive_anchor: wire_receipt.primitive_anchor,
        xy_digest: wire_receipt.xy_digest,
        pd_binding_digest: wire_receipt.pd_binding_digest,
        pd_continuum_activation_digest: wire_receipt.pd_continuum_activation_digest,
        living_trust_digest: wire_receipt.living_trust_digest,
        living_trust_sha256: hex32(&wire_receipt.living_trust_sha256),
        y_verdict: wire_receipt.y_verdict,
        x_verdict: wire_receipt.x_verdict,
        seal: wire_receipt.seal,
        generation: wire_receipt.generation,
        receipt_id: wire_receipt.receipt_id.clone(),
    };
    let identity = identity_digest(
        &receipt.session_id,
        &receipt.parent_i0,
        receipt.primitive_anchor,
    );
    let binding = NativeRequestBinding {
        model_case: None,
        identity_digest: identity,
        request_sha256: prepared.source_request_sha256,
        prepared: prepared_bytes,
        kie_proof: Vec::new(),
    };
    // Source fixture lineage/write structure, with explicitly synthetic payload.
    // confirm validates the pair/type; it is NOT a native GCL judgement here.
    let verdict = LawConfirmedVerdict::confirm(supreme(&response.verdict), negative)
        .expect("fixture constitutional pair");
    let mut base = crate::vault_transaction::test_support::sample_transaction();
    base.lineage.input_id = input_id;
    let writes = if negative {
        vec![KnowledgeWrite::Negative {
            input_id,
            raw_bytes: NOTICE.as_bytes().to_vec(),
            context: NegativeContext {
                failure_reason_code: 1,
                process: "SYNTHETIC_T2_STORAGE_TEST".into(),
                mass_at_fail: 0.0,
                frequency: 1,
            },
            ts_ns: 48,
        }]
    } else {
        for write in &mut base.knowledge_writes {
            match write {
                KnowledgeWrite::Primitive {
                    input_id: id,
                    raw_bytes,
                    domain,
                    ..
                } => {
                    *id = input_id;
                    *raw_bytes = NOTICE.as_bytes().to_vec();
                    *domain = "synthetic-storage-fixture".into();
                }
                KnowledgeWrite::Negative { .. } => panic!("unexpected source fixture"),
            }
        }
        base.knowledge_writes
    };
    let cycle = crate::vault_transaction::sha256_parts(&[
        b"SYNTHETIC_T2_STORAGE_TEST_CYCLE",
        &identity,
        kind.as_bytes(),
        &input_id.to_le_bytes(),
    ]);
    let transaction = VaultTransaction::build(
        identity,
        cycle,
        base.anchor_generation,
        base.negative_batch_digest,
        base.runtime_delta_digest,
        base.vds_close_digest,
        base.law0_digest,
        &verdict,
        writes,
        base.lineage,
        None,
        receipt,
    )
    .with_native_cycle(NativeCycleSnapshot::new(&binding, response).unwrap())
    .expect("actual T1 transaction and prepared snapshot validation");
    Fixture {
        transaction,
        identity,
        request_sha256: binding.request_sha256,
        expected,
    }
}

struct TempWal {
    directory: PathBuf,
    path: PathBuf,
}
impl TempWal {
    fn new(label: &str) -> Self {
        static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        for _ in 0..1024 {
            let serial = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            let directory = std::env::temp_dir().join(format!(
                "essmai_t2_synthetic_{label}_{}_{}",
                std::process::id(),
                serial,
            ));
            match std::fs::create_dir(&directory) {
                Ok(()) => {
                    return Self {
                        path: directory.join("fixture.wal"),
                        directory,
                    }
                }
                Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(e) => panic!("create isolated test directory: {e}"),
            }
        }
        panic!("isolated fixture directory exhaustion");
    }
}
impl Drop for TempWal {
    fn drop(&mut self) {
        // Remove only the exact file/directory created by this fixture helper.
        let _ = std::fs::remove_file(&self.path);
        let _ = std::fs::remove_dir(&self.directory);
    }
}

fn counts(vault: &KnowledgeVault) -> (usize, usize) {
    (vault.primitive_count(), vault.negative_count())
}

// R20 independent test oracle for the existing source formulas. This deliberately
// does not call derive_continuation, digest_parts or continuation_question.
// D is the source 64-bit recurrence; H is SHA-256. D is not a cryptographic seal.
fn formula_digest(parts: &[&[u8]]) -> u64 {
    let mut value = 0xcbf2_9ce4_8422_2325u64;
    for byte in parts.iter().flat_map(|part| part.iter()) {
        value = (value ^ u64::from(*byte)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    value
}

fn assert_continuation_formula(record: &NativeContinuationRecord, commit: &crate::vault_transaction::DurableCommit) {
    let source = commit.native_cycle.as_ref().unwrap();
    let prepared = pd::decode_prepared(&source.prepared).unwrap();
    let response = shadow_contracts::decode_cycle_response(&source.response).unwrap();
    let actual = pd::decode_continuation(&record.material).unwrap();
    let p = &prepared.pending;
    let r = &response.verification_receipt;
    let v = &response.verdict;
    // These six fixture scenarios contain no failure-witness override.
    assert!(prepared.failure_witness.is_none());
    let (basis, label, question) = match (r.y_verdict, r.x_verdict) {
        (1, 1) => (1, "VERIFIED_POSITIVE", p.prepared_question.clone()),
        (0, 0) => (2, "VERIFIED_NEGATIVE_REBUILD", format!("Cila provë konkrete duhet të zëvendësojë bazën e rrëzuar: {}", p.prepared_question)),
        _ => panic!("mixed pair cannot have a continuation"),
    };
    assert_eq!((actual.basis, actual.y_verdict, actual.x_verdict), (basis, r.y_verdict, r.x_verdict));
    assert_eq!(actual.question, question);
    let version = 0x0001_0601u32.to_le_bytes();
    let activation = p.spine.continuum.activation_digest.to_le_bytes();
    let increment = p.spine.continuum.increment_digest.to_le_bytes();
    let binding = r.pd_binding_digest.to_le_bytes();
    let trust = hex32(&v.living_trust_sha256);
    let td = formula_digest(&[&trust, &v.living_trust_intensity.to_le_bytes(), &[v.living_trust_kind],
        &v.living_trust_sovereign_value.to_le_bytes(), b"GCL_LIVING_TRUST_TO_IZ_V164"]);
    let output = formula_digest(&[&version, &activation, &binding, &increment, r.receipt_id.as_bytes(),
        question.as_bytes(), &[r.y_verdict], &[r.x_verdict], label.as_bytes(), b"PD_VERIFIED_OUTPUT"]);
    let iz = formula_digest(&[&version, &activation, &increment, &output.to_le_bytes(), &td.to_le_bytes(),
        r.receipt_id.as_bytes(), label.as_bytes(), b"PD_COMPLETES_IZ_WITH_LIVING_TRUST_V161"]);
    let next = format!("i0-{:016x}", formula_digest(&[&version, &output.to_le_bytes(), &iz.to_le_bytes(), b"PD_OUTPUT_PLUS_IZ_TO_NEXT_I0"]));
    let complete = formula_digest(&[&version, &activation, &increment, &output.to_le_bytes(), &iz.to_le_bytes(),
        &td.to_le_bytes(), next.as_bytes(), r.receipt_id.as_bytes(), label.as_bytes(), b"PD_CONTINUUM_COMPLETE"]);
    assert_eq!((actual.living_trust_digest, actual.pd_output_digest, actual.iz_digest, actual.continuum_completion_digest), (td, output, iz, complete));
    assert_eq!((actual.pd_output_id.as_str(), actual.iz_id.as_str(), actual.next_i0_id.as_str()),
        (format!("pdo-{output:016x}").as_str(), format!("iZ-{iz:016x}").as_str(), next.as_str()));
    let mut iz_preimage = b"ESS_MAI_IZ_V157".to_vec();
    for part in [&activation[..], &increment[..], &output.to_le_bytes()[..], r.receipt_id.as_bytes(), &trust[..],
        &v.living_trust_intensity.to_le_bytes()[..], &[v.living_trust_kind][..],
        &v.living_trust_sovereign_value.to_le_bytes()[..], &td.to_le_bytes()[..],
        &p.pre_seal.action_sha256[..], &p.pre_seal.law_trace_sha256[..]] {
        iz_preimage.extend_from_slice(part);
    }
    assert_eq!(actual.iz_sha256, <[u8;32]>::from(Sha256::digest(&iz_preimage)));
    assert_eq!(actual.prepared_sha256, <[u8;32]>::from(Sha256::digest(&source.prepared)));
    assert_eq!(actual.shadow_response_sha256, <[u8;32]>::from(Sha256::digest(&source.response)));
    assert_eq!(actual.source_request_sha256, record.request_sha256);
    assert_eq!(record.transaction_id, commit.transaction_id);
    let encoded = record.encode().unwrap();
    assert_eq!(&encoded[encoded.len()-32..], Sha256::digest(&encoded[..encoded.len()-32]).as_slice());
}

// Count actual protected WAL frames independently of the runtime replay engine.
// F = LEN || !LEN || CRC32(LEN || payload) || payload; only T1/T2 are allowed here.
fn wal_counts(bytes: &[u8]) -> (usize, usize) {
    assert_eq!(&bytes[..8], &0x474a_5356_4c30_3401u64.to_le_bytes());
    assert_eq!(&bytes[8..12], &3u32.to_le_bytes());
    let (mut cursor, mut result) = (12, (0, 0));
    while cursor < bytes.len() {
        let n = u32::from_le_bytes(bytes[cursor..cursor+4].try_into().unwrap());
        assert_eq!(u32::from_le_bytes(bytes[cursor+4..cursor+8].try_into().unwrap()), !n);
        let end = cursor + 12 + n as usize;
        let payload = &bytes[cursor+12..end];
        let mut crc = !0u32;
        for byte in bytes[cursor..cursor+4].iter().chain(payload.iter()) {
            crc ^= u32::from(*byte);
            for _ in 0..8 { crc = (crc >> 1) ^ (0xedb8_8320u32 & (crc & 1).wrapping_neg()); }
        }
        assert_eq!(u32::from_le_bytes(bytes[cursor+8..cursor+12].try_into().unwrap()), !crc);
        match payload[0] { 5 => result.0 += 1, 7 => result.1 += 1, tag => panic!("unexpected fixture frame {tag}") }
        cursor = end;
    }
    assert_eq!(cursor, bytes.len());
    result
}

// Canonical knowledge_vault::apply_primitive keys entries by FNV64(raw_bytes),
// not transaction/input identity. Repeated content adds a trace to one entry.
// These bounded fixtures contain at most one negative write, so no approximate
// negative-pattern dedup rule is inferred from an additive count here.
fn fixture_knowledge_union(transactions: &[&VaultTransaction]) -> (usize, usize) {
    let mut positives = std::collections::BTreeMap::<u64, Vec<u8>>::new();
    let mut positive_ids = std::collections::BTreeSet::new();
    let mut negative_writes = 0;
    for tx in transactions {
        for write in &tx.knowledge_writes {
            match write {
                KnowledgeWrite::Primitive { input_id, raw_bytes, .. } => {
                    assert!(positive_ids.insert(*input_id), "fixture cycles use distinct positive input identities");
                    match positives.insert(formula_digest(&[raw_bytes]), raw_bytes.clone()) {
                        Some(prior) => assert_eq!(&prior, raw_bytes, "fixture dedup is equal bytes, not a hash collision"),
                        None => {}
                    }
                }
                KnowledgeWrite::Negative { .. } => negative_writes += 1,
            }
        }
    }
    assert!(negative_writes <= 1, "this bounded oracle does not replace negative pattern dedup");
    (positives.len(), negative_writes)
}

#[test]
fn real_disk_t1_reopen_t2_is_exact_and_retry_does_not_append() {
    for (index, kind) in ["positive", "negative"].iter().enumerate() {
        let f = fixture(kind, 0xF0E1_D2C3_B4A5_0800 + index as u64);
        let wal = TempWal::new(kind);
        let commit;
        let initial_counts;
        {
            let vault = KnowledgeVault::open_disk(&wal.path).expect("new isolated disk Vault");
            commit = vault
                .commit_test_transaction(f.transaction)
                .expect("actual T1 WAL commit");
            assert_eq!(commit.status, CommitStatus::Committed);
            initial_counts = counts(&vault);
            assert_eq!(
                initial_counts,
                if *kind == "positive" { (1, 0) } else { (0, 1) }
            );
        }
        let t1_bytes = std::fs::read(&wal.path).unwrap();
        assert_eq!(wal_counts(&t1_bytes), (1, 0), "durable T1 is not yet T2");
        let record;
        {
            let vault = KnowledgeVault::open_disk(&wal.path).expect("restart after T1 only");
            drop(vault); // Windows WAL locks exclude separate file readers.
            assert_eq!(std::fs::read(&wal.path).unwrap(), t1_bytes);
            let vault = KnowledgeVault::open_disk(&wal.path).expect("reopen inspected T1");
            let restored = vault
                .committed_identity(&f.identity)
                .unwrap()
                .expect("T1 restored");
            assert_eq!(restored.transaction_id, commit.transaction_id);
            assert_eq!(restored.native_cycle, commit.native_cycle);
            record = vault
                .finalize_native_continuation(f.identity, f.request_sha256)
                .expect("Shadow-derived durable T2");
            assert_eq!(record.material, f.expected);
            assert_eq!(record.transaction_id, commit.transaction_id);
            record
                .validate_against(&restored)
                .expect("exact T1 binding");
            assert_continuation_formula(&record, &restored);
            assert_eq!(counts(&vault), initial_counts, "T2 adds no knowledge");
            drop(vault);
            let t2_bytes = std::fs::read(&wal.path).unwrap();
            assert_eq!(wal_counts(&t2_bytes), (1, 1), "one T1 produces one T2");
            assert!(
                t2_bytes.len() > t1_bytes.len(),
                "T2 really appended to the same WAL"
            );
            let vault = KnowledgeVault::open_disk(&wal.path).expect("restart for T2 retry");
            let repeat = vault
                .finalize_native_continuation(f.identity, f.request_sha256)
                .expect("idempotent T2 retry");
            assert_eq!(repeat.encode().unwrap(), record.encode().unwrap());
            drop(vault);
            assert_eq!(
                std::fs::read(&wal.path).unwrap(),
                t2_bytes,
                "retry must not append"
            );
            let vault = KnowledgeVault::open_disk(&wal.path).expect("restart for refused lookups");
            let mut wrong_request = f.request_sha256;
            wrong_request[0] ^= 1;
            assert!(vault
                .finalize_native_continuation(f.identity, wrong_request)
                .is_err());
            let mut wrong_identity = f.identity;
            wrong_identity[0] ^= 1;
            assert!(vault
                .finalize_native_continuation(wrong_identity, f.request_sha256)
                .is_err());
            drop(vault);
            assert_eq!(
                std::fs::read(&wal.path).unwrap(),
                t2_bytes,
                "refusal must not append"
            );
        }
        let completed = std::fs::read(&wal.path).unwrap();
        {
            let vault = KnowledgeVault::open_disk(&wal.path).expect("restart after T1 and T2");
            let replay = vault
                .finalize_native_continuation(f.identity, f.request_sha256)
                .expect("replayed T2");
            assert_eq!(replay, record);
            assert_eq!(counts(&vault), initial_counts);
            drop(vault);
            assert_eq!(
                std::fs::read(&wal.path).unwrap(),
                completed,
                "restart/retry is byte-identical"
            );
        }
    }
    println!(r#"R20_MATH {{"test":"real_disk_t1_reopen_t2_is_exact_and_retry_does_not_append","checks":["T2_EQUAL_F_T1","IZ_FORMULA_ORACLE","T1_T2_FRAME_CARDINALITY","DELTA_KNOWLEDGE_T2_ZERO","RETRY_WAL_BYTES_FIXED","POLARITY_PRESERVED"]}}"#);
}

// Adds only a consistent but incomplete NEXT frame header. It is safe to repair
// only if the entire preceding stream has passed semantic validation.
fn append_torn_header(path: &Path) {
    let complete = std::fs::read(path).unwrap();
    assert!(complete.len() >= 20);
    let mut file = std::fs::OpenOptions::new().append(true).open(path).unwrap();
    file.write_all(&complete[12..20]).unwrap();
    file.sync_all().unwrap();
}

fn assert_corrupt_replay_preserves_file(path: &Path, expected_code: &str) {
    let before = std::fs::read(path).unwrap();
    let error = match KnowledgeVault::open_disk(path) {
        Ok(_) => panic!("semantic corruption must reject opening with {expected_code}"),
        Err(error) => format!("{error:?}"),
    };
    assert!(error.contains("semantic replay:") && error.contains(expected_code),
        "expected semantic replay rejection {expected_code}, received {error}");
    assert_eq!(
        std::fs::read(path).unwrap(),
        before,
        "rejection must not repair/truncate"
    );
}

#[test]
fn foreign_t1_or_altered_t2_is_rejected_before_any_torn_tail_repair() {
    for (kind_index, kind) in ["positive", "negative"].iter().enumerate() {
        for mutation in 0..8u64 {
            let f = fixture(
                kind,
                0xF0E1_D2C3_B4A5_0810 + 8 * kind_index as u64 + mutation,
            );
            let wal = TempWal::new("corrupt");
            let mut record;
            {
                let vault = KnowledgeVault::open_disk(&wal.path).unwrap();
                let commit = vault.commit_test_transaction(f.transaction).unwrap();
                record = NativeContinuationRecord::derive(f.identity, f.request_sha256, &commit)
                    .unwrap();
            }
            match mutation {
                0 => record.transaction_id[0] ^= 1, // T2 points to another T1.
                1 => record.request_sha256[0] ^= 1, // Same identity, substituted original request.
                2 => {
                    let mut material = pd::decode_continuation(&record.material).unwrap();
                    material.iz_sha256[0] ^= 1; // Rechecksummed data, not a trivial checksum failure.
                    record.material = pd::encode_continuation(&material).unwrap();
                }
                3 => record.identity[0] ^= 1,
                4..=6 => {
                    let mut material = pd::decode_continuation(&record.material).unwrap();
                    match mutation {
                        4 => material.prepared_sha256[0] ^= 1,
                        5 => material.source_request_sha256[0] ^= 1,
                        6 => material.shadow_response_sha256[0] ^= 1,
                        _ => unreachable!(),
                    }
                    record.material = pd::encode_continuation(&material).unwrap();
                }
                7 => {
                    // An entirely valid opposite-polarity continuation still
                    // cannot substitute for F(this T1), despite valid checksums.
                    let other_kind = match *kind { "positive" => "negative", _ => "positive" };
                    let other = fixture(other_kind, 0xF0E1_D2C3_B4A5_0880 + kind_index as u64);
                    let other_wal = TempWal::new("other-polarity");
                    let other_vault = KnowledgeVault::open_disk(&other_wal.path).unwrap();
                    let other_commit = other_vault.commit_test_transaction(other.transaction).unwrap();
                    record.material = NativeContinuationRecord::derive(other.identity, other.request_sha256, &other_commit).unwrap().material;
                }
                _ => unreachable!(),
            }
            let encoded = record
                .encode()
                .expect("shape-valid, publicly rechecksummed forged record");
            assert_eq!(NativeContinuationRecord::decode(&encoded).unwrap(), record);
            {
                // Low-level test-only WAL writer permits a self-consistent frame;
                // authoritative replay must still rederive from T1 and reject it.
                let (backend, _) = DiskBackend::open(&wal.path).unwrap();
                backend.commit_native_continuation(&record).unwrap();
            }
            let expected_code = match mutation {
                1 => "PD_T1_REQUEST_CONFLICT",
                3 => "PD_T2_WITHOUT_T1",
                _ => "PD_T2_DERIVATION_MISMATCH",
            };
            assert_corrupt_replay_preserves_file(&wal.path, expected_code);
            append_torn_header(&wal.path);
            assert_corrupt_replay_preserves_file(&wal.path, expected_code);
        }
    }
    println!(r#"R20_MATH {{"test":"foreign_t1_or_altered_t2_is_rejected_before_any_torn_tail_repair","checks":["OUTER_HASH_NOT_AUTHORITY","EXACT_T1_IDENTITY_AND_TRANSACTION","EXACT_PREPARED_REQUEST_RESPONSE_HASHES","VALID_OTHER_POLARITY_NOT_SUBSTITUTABLE","SEMANTIC_FAILURE_BEFORE_REPAIR"]}}"#);
}

#[test]
fn t2_without_its_t1_is_refused_even_with_a_repairable_tail() {
    for (index, kind) in ["positive", "negative"].iter().enumerate() {
    let f = fixture(kind, 0xF0E1_D2C3_B4A5_0830 + index as u64);
    let source = TempWal::new("source");
    let record = {
        let vault = KnowledgeVault::open_disk(&source.path).unwrap();
        let commit = vault.commit_test_transaction(f.transaction).unwrap();
        NativeContinuationRecord::derive(f.identity, f.request_sha256, &commit).unwrap()
    };
    let orphan = TempWal::new("orphan");
    {
        let (backend, _) = DiskBackend::open(&orphan.path).unwrap();
        backend.commit_native_continuation(&record).unwrap();
    }
    assert_corrupt_replay_preserves_file(&orphan.path, "PD_T2_WITHOUT_T1");
    append_torn_header(&orphan.path);
    assert_corrupt_replay_preserves_file(&orphan.path, "PD_T2_WITHOUT_T1");
    }
    println!(r#"R20_MATH {{"test":"t2_without_its_t1_is_refused_even_with_a_repairable_tail","checks":["T2_IMPLIES_EXISTING_T1_BOTH_POLARITIES","ORPHAN_REFUSAL_PRESERVES_BYTES","TORN_SUFFIX_CANNOT_REPAIR_INVALID_PREFIX"]}}"#);
}

fn write_new(path: &Path, bytes: &[u8]) {
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .expect("fixture exporter refuses existing output");
    file.write_all(bytes).unwrap();
    file.sync_all().unwrap();
}

#[test]
fn export_synthetic_t1_only_wals_for_shadow_process() {
    let owned_output = crate::test_output::OutputDir::new("ESSMAI_PD_T2_FIXTURE_DIR", "t1");
    let output = owned_output.path();
    for (index, kind) in ["positive", "negative"].iter().enumerate() {
        let f = fixture(kind, 0xF0E1_D2C3_B4A5_0840 + index as u64);
        let dir = output.join(kind);
        std::fs::create_dir(&dir).expect("each export subdirectory must be new");
        let wal = dir.join("shadow_wisdom.svlt");
        write_new(&wal, b""); // Exclusively reserve the intended new WAL path.
        {
            let vault = KnowledgeVault::open_disk(&wal).unwrap();
            let committed = vault.commit_test_transaction(f.transaction).unwrap();
            assert_eq!(committed.status, CommitStatus::Committed);
            assert_eq!(counts(&vault), match *kind { "positive" => (1, 0), _ => (0, 1) });
            // Deliberately NO finalize call here. Production Shadow must append T2.
        }
        let t1_only = std::fs::read(&wal).unwrap();
        assert_eq!(wal_counts(&t1_only), (1, 0), "export contains no durable T2 reference");
        {
            let reopened = KnowledgeVault::open_disk(&wal).unwrap();
            assert_eq!(counts(&reopened), match *kind { "positive" => (1, 0), _ => (0, 1) });
            let restored = reopened.committed_identity(&f.identity).unwrap().unwrap();
            let data_only = NativeContinuationRecord::derive(f.identity, f.request_sha256, &restored).unwrap();
            assert_continuation_formula(&data_only, &restored);
            assert_eq!(data_only.material, f.expected);
        }
        assert_eq!(std::fs::read(&wal).unwrap(), t1_only, "reopen/formula derivation do not append T2");
        write_new(
            &dir.join("lookup.bin"),
            &shadow_contracts::pd_cycle::finalize_lookup(f.identity, f.request_sha256),
        );
        write_new(&dir.join("expected_continuation.bin"), &f.expected);
        write_new(&dir.join("FIXTURE_NOTICE.txt"), NOTICE.as_bytes());
        let manifest = format!(
            "classification=SYNTHETIC_STORAGE_FORMULA_FIXTURE\nkind={kind}\nT1_only=true\nnative_GCL_admission=false\nrequest_sha256={}\nidentity={}\nexpected_continuation_sha256={}\nT1_wal_sha256={}\n",
            crate::living_trust_contract::hex_32(&f.request_sha256),
            crate::living_trust_contract::hex_32(&f.identity),
            crate::living_trust_contract::hex_32(&Sha256::digest(&f.expected).into()),
            crate::living_trust_contract::hex_32(&Sha256::digest(std::fs::read(&wal).unwrap()).into()),
        );
        write_new(&dir.join("fixture_manifest.txt"), manifest.as_bytes());
        println!("SYNTHETIC_T1_ONLY_WAL={}", wal.display());
    }
    println!(r#"R20_MATH {{"test":"export_synthetic_t1_only_wals_for_shadow_process","checks":["EXPORT_T1_ONLY_NO_T2","EXPORT_EXACT_KNOWLEDGE_COUNTS","REOPEN_PRESERVES_T1_BYTES","PURE_DERIVATION_GRANTS_NO_DURABILITY"]}}"#);
}

#[test]
fn t1_precommit_refuses_receipt_activation_and_negative_persistence_mismatch() {
    for (kind_index, kind) in ["positive", "negative"].iter().enumerate() {
        for fault in 0..4u64 {
            let f = fixture(kind, 0xF0E1_D2C3_B4A5_0850 + 8 * kind_index as u64 + fault);
            let mut original = f.transaction;
            let mut snapshot = original
                .native_cycle
                .take()
                .expect("valid fixture snapshot");
            let mut response = shadow_contracts::decode_cycle_response(&snapshot.response).unwrap();
            if fault != 1 {
                // Keep receipt and response mutually consistent, including the
                // receipt's own source-formula ID. Only prepared activation is
                // different: T1 must reject this semantic mismatch before WAL.
                match fault {
                    0 => original.receipt.pd_continuum_activation_digest ^= 1,
                    2 => original.receipt.pd_binding_digest ^= 1,
                    3 => original.receipt.living_trust_digest ^= 1,
                    _ => unreachable!(),
                }
                let r = &mut original.receipt;
                r.receipt_id = crate::lab_contracts::verification_receipt::receipt_id(
                    &r.session_id,
                    &r.parent_i0,
                    r.primitive_anchor,
                    r.xy_digest,
                    r.pd_binding_digest,
                    r.pd_continuum_activation_digest,
                    &r.living_trust_sha256,
                    r.y_verdict,
                    r.x_verdict,
                    r.generation,
                    r.seal,
                );
                response.verification_receipt.pd_continuum_activation_digest =
                    r.pd_continuum_activation_digest;
                response.verification_receipt.pd_binding_digest = r.pd_binding_digest;
                response.verification_receipt.living_trust_digest = r.living_trust_digest;
                response.verification_receipt.receipt_id = r.receipt_id.clone();
            } else {
                // Especially significant for a negative pair: false used to
                // bypass the old one-direction "true requires a negative write".
                response.negative_persisted = !response.negative_persisted;
            }
            let verdict =
                LawConfirmedVerdict::confirm(supreme(&response.verdict), *kind == "negative")
                    .unwrap();
            let rebuilt = VaultTransaction::build(
                original.identity_digest,
                original.cycle_digest,
                original.anchor_generation,
                original.negative_batch_digest,
                original.runtime_delta_digest,
                original.vds_close_digest,
                original.law0_digest,
                &verdict,
                original.knowledge_writes,
                original.lineage,
                original.gcl_reinforcement,
                original.receipt,
            );
            snapshot.response = shadow_contracts::encode_cycle_response(&response);
            assert!(rebuilt.with_native_cycle(snapshot).is_err(),
                "T1 constructor must reject kind={kind} fault={fault}; no disk commit was attempted");
        }
    }
    println!(r#"R20_MATH {{"test":"t1_precommit_refuses_receipt_activation_and_negative_persistence_mismatch","checks":["T1_ACTIVATION_EQUALS_PREPARED","T1_BINDING_EQUALS_PENDING","T1_LIVING_TRUST_FORMULA","NEGATIVE_PERSISTENCE_MATCHES_DURABLE_WRITES","RECHECKSUMMED_RECEIPT_INSUFFICIENT"]}}"#);
}

#[test]
fn native_pd_followup_requires_durable_t2_and_latest_head_across_reopen() {
    // Both available successor exports have this exact positive parent. A
    // negative child is a real change of verdict; its history is not relabeled.
    for child_kind in ["followup-positive", "followup-negative"] {
    let first=fixture("positive",0xF0E1_D2C3_B4A5_0900);
    let wal=TempWal::new("pd-head");
    let root_commit;
    let child;
    let sibling;
    let expected_knowledge;
    {
        let vault=KnowledgeVault::open_disk(&wal.path).unwrap();
        root_commit=vault.commit_test_transaction(first.transaction.clone()).unwrap();
        child=fixture_with_predecessor(child_kind,0xF0E1_D2C3_B4A5_0901,Some(&root_commit));
        sibling=fixture_with_predecessor("stale-positive",0xF0E1_D2C3_B4A5_0902,Some(&root_commit));
        expected_knowledge=fixture_knowledge_union(&[&first.transaction,&child.transaction]);
        assert_eq!(expected_knowledge,match child_kind { "followup-positive"=>(1,0),_=>(1,1) },
            "distinct cycles preserve the canonical union of candidate keys");
        let before=counts(&vault);
        assert!(format!("{:?}",vault.commit_test_transaction(child.transaction.clone()).unwrap_err()).contains("T2_NOT_DURABLE"));
        assert_eq!(counts(&vault),before);
        assert!(vault.committed_identity(&child.identity).unwrap().is_none());
        let root_t2=vault.finalize_native_continuation(first.identity,first.request_sha256).unwrap();
        assert_continuation_formula(&root_t2,&root_commit);
        let child_commit=vault.commit_test_transaction(child.transaction.clone()).unwrap();
        assert_eq!(child_commit.status,CommitStatus::Committed);
        assert_eq!(counts(&vault),expected_knowledge);
        let child_t2=vault.finalize_native_continuation(child.identity,child.request_sha256).unwrap();
        assert_continuation_formula(&child_t2,&child_commit);
        assert_eq!(pd::decode_continuation(&child_t2.material).unwrap().basis,
            match child_kind { "followup-positive"=>1,_=>2 });
        assert!(format!("{:?}",vault.commit_test_transaction(sibling.transaction.clone()).unwrap_err()).contains("NOT_CURRENT_HEAD"));
        assert_eq!(vault.commit_test_transaction(first.transaction.clone()).unwrap().status,CommitStatus::AlreadyCommitted);
        assert_eq!(vault.finalize_native_continuation(first.identity,first.request_sha256).unwrap(),root_t2);
        assert!(format!("{:?}",vault.commit_test_transaction(sibling.transaction.clone()).unwrap_err()).contains("NOT_CURRENT_HEAD"),
            "old exact retry must not roll the current head back");
    }
    let before=std::fs::read(&wal.path).unwrap();
    assert_eq!(wal_counts(&before),(2,2),"two distinct cycles each have exactly one T1/T2");
    {
        let vault=KnowledgeVault::open_disk(&wal.path).unwrap();
        assert_eq!(vault.commit_test_transaction(child.transaction.clone()).unwrap().status,CommitStatus::AlreadyCommitted);
        assert!(format!("{:?}",vault.commit_test_transaction(sibling.transaction.clone()).unwrap_err()).contains("NOT_CURRENT_HEAD"));
        let binding=NativeRequestBinding {model_case:None,identity_digest:sibling.identity,request_sha256:sibling.request_sha256,
            prepared:sibling.transaction.native_cycle.as_ref().unwrap().prepared.clone(),kie_proof:Vec::new()};
        assert!(vault.validate_native_pd_admission(&binding).is_err());
        assert_eq!(vault.committed_identity(&first.identity).unwrap().unwrap().transaction_id,root_commit.transaction_id);
        assert_eq!(counts(&vault),expected_knowledge);
        let old=vault.finalize_native_continuation(first.identity,first.request_sha256).unwrap();
        assert_continuation_formula(&old,&root_commit);
        assert!(format!("{:?}",vault.commit_test_transaction(sibling.transaction.clone()).unwrap_err()).contains("NOT_CURRENT_HEAD"));
    }
    assert_eq!(std::fs::read(&wal.path).unwrap(),before,"retry and stale refusal append no WAL bytes");
    // A self-consistent frame from a stale branch must fail semantic replay,
    // before repairing even a genuinely incomplete suffix.
    {
        let (backend,_)=DiskBackend::open(&wal.path).unwrap();
        backend.commit_test_transaction(&sibling.transaction).unwrap();
    }
    assert_corrupt_replay_preserves_file(&wal.path, "PD_NATIVE_PREDECESSOR_NOT_CURRENT_HEAD");
    append_torn_header(&wal.path);
    assert_corrupt_replay_preserves_file(&wal.path, "PD_NATIVE_PREDECESSOR_NOT_CURRENT_HEAD");
    }
    println!(r#"R20_MATH {{"test":"native_pd_followup_requires_durable_t2_and_latest_head_across_reopen","checks":["CHILD_REQUIRES_DURABLE_PARENT_T2","CURRENT_HEAD_COMPARE_AND_SWAP","POSITIVE_TO_POSITIVE_OR_NEGATIVE","KNOWLEDGE_COUNT_IS_CANDIDATE_KEY_UNION","OLD_RETRY_CANNOT_ROLL_BACK_HEAD","TWO_CYCLES_EXACTLY_TWO_T1_TWO_T2","STALE_BRANCH_REFUSED_ON_REPLAY"]}}"#);
}

